**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <queue>
using namespace std;

const int N = 7;
int tab[N][N];
bool visited[N][N];
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

pair<int,bool> bfs(int si, int sj) {
    queue<pair<int,int>> q;
    q.push({si, sj});
    visited[si][sj] = true;
    int rozmiar = 0;
    bool brzeg = false;
    while (!q.empty()) {
        auto [i, j] = q.front(); q.pop();
        rozmiar++;
        if (i == 0 || i == N-1 || j == 0 || j == N-1)
            brzeg = true;
        for (int d = 0; d < 4; d++) {
            int ni = i + dx[d], nj = j + dy[d];
            if (ni >= 0 && ni < N && nj >= 0 && nj < N
                && !visited[ni][nj] && tab[ni][nj] == 1) {
                visited[ni][nj] = true;
                q.push({ni, nj});
            }
        }
    }
    return {rozmiar, brzeg};
}

int main() {
    ifstream plik("dane.txt");
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            plik >> tab[i][j];

    int total = 0, brzegowe = 0;
    vector<int> wewnetrzne;

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (tab[i][j] == 1 && !visited[i][j]) {
                auto [roz, brz] = bfs(i, j);
                total++;
                if (brz)
                    brzegowe++;
                else
                    wewnetrzne.push_back(roz);
            }

    cout << "a) Wyspy lacznie: " << total << endl;
    cout << "b) Wyspy brzegowe: " << brzegowe << endl;
    cout << "c) Wyspy wewnetrzne: " << (int)wewnetrzne.size() << endl;
    cout << "d) Rozmiary wewnetrznych:";
    for (int r : wewnetrzne) cout << " " << r;
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: BFS dla kazdej wyspy. Podczas BFS sprawdzamy, czy ktoras komorka jest na brzegu. Wyspy bez komorek brzegowych to wyspy wewnetrzne.

Weryfikacja:
```
  j: 0 1 2 3 4 5 6
i=0: 1 1 0 0 0 0 1
i=1: 1 0 0 0 0 0 0
i=2: 0 0 1 1 0 0 0
i=3: 0 0 1 1 0 0 0
i=4: 0 0 0 0 0 1 0
i=5: 0 0 0 0 0 0 0
i=6: 1 0 0 0 0 0 1
```
Wyspy (skanowanie wierszami):
1. Start (0,0): (0,0)-(0,1)-(1,0) = 3 komorki. (0,0) na brzegu -> BRZEGOWA
2. Start (0,6): (0,6) = 1 komorka. (0,6) na brzegu -> BRZEGOWA
3. Start (2,2): (2,2)-(2,3)-(3,2)-(3,3) = 4 komorki. Zadna na brzegu -> WEWNETRZNA
4. Start (4,5): (4,5) = 1 komorka. i=4, j=5 — nie na brzegu -> WEWNETRZNA
5. Start (6,0): (6,0) = 1 komorka. (6,0) na brzegu -> BRZEGOWA
6. Start (6,6): (6,6) = 1 komorka. (6,6) na brzegu -> BRZEGOWA

Lacznie: 6. Brzegowe: 4. Wewnetrzne: 2. Rozmiary wewnetrznych: 4, 1.
